user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning expresses an intended future course of action, committing the agent to one or more operations it has not yet performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly states at least one action or step the agent intends to perform next.",
      "The intended step is future-oriented with respect to the reasoning node, optionally accompanied by ordering or purpose."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions or results already completed.",
      "The reasoning restates an external requirement or constraint without committing to a future action."
    ]
  },
  {
    "name": "PREDICTS_RESIDUAL_ARTIFACT_INTERFERENCE",
    "definition": "The reasoning predicts that state left behind by the agent's own testing or configuration work will cause a later required operation, typically performed by the end user or an external checker, to fail or behave incorrectly, and uses that prediction to justify removing or resetting that state.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that identifies leftover state, predicts its adverse effect on a later operation, and motivates its removal."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies specific residual state created by the agent's own activity, such as test commits, branches, keys, or files.",
      "The reasoning predicts a concrete adverse consequence for a later operation, for example that a commit will fail because nothing changed or that a push will report nothing to update.",
      "The prediction is used as the reason for removing or resetting the identified state before handoff."
    ],
    "exclusion_conditions": [
      "The reasoning expresses generic cleanliness or tidiness concerns without a predicted operational consequence.",
      "The predicted consequence is unrelated to state created by the agent itself.",
      "The reasoning plans cleanup only because the state is no longer needed, with no predicted interference."
    ]
  },
  {
    "name": "EXPLAINS_OBSERVED_FAILURE_CAUSE",
    "definition": "The reasoning assigns a specific causal explanation to a failure reported in the observation, identifying the mechanism by which the failure arose rather than merely restating the error text.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text containing the causal explanation of the failure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the error or failed operation being explained."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, non-zero exit, or otherwise failed outcome.",
      "The reasoning names a concrete cause that goes beyond the error message, such as a missing environment variable on a later subcommand or an ownership mismatch between user and repository.",
      "The stated cause is consistent with the content of the observation."
    ],
    "exclusion_conditions": [
      "The reasoning only repeats or paraphrases the error message without explaining it.",
      "The reasoning attributes the failure to an unidentified or vague cause.",
      "The stated cause contradicts the observation's reported facts."
    ]
  },
  {
    "name": "ATTRIBUTES_FAILURE_TO_TEST_HARNESS_ARTIFACT",
    "definition": "The reasoning classifies an observed failure as an artifact of the agent's own test instrumentation or simulated conditions rather than as a defect in the configured system or something the end user would encounter.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that reinterprets the failure as a test-side artifact."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure whose origin is being classified."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure that occurred during the agent's own verification procedure.",
      "The reasoning states that the failure stems from the agent's test setup, simulated credentials, or missing test-side configuration, rather than from the delivered system.",
      "The reasoning contrasts the test conditions with the conditions the end user will actually use."
    ],
    "exclusion_conditions": [
      "The reasoning treats the failure as a genuine defect in the delivered configuration.",
      "The reasoning makes no distinction between test-side and user-side conditions.",
      "The reasoning accepts the failure without interpreting its origin."
    ]
  },
  {
    "name": "REVISES_APPROACH_IN_RESPONSE_TO_FAILURE",
    "definition": "The reasoning specifies a concrete modified approach that differs from the attempt that failed and is intended to avoid the identified cause, instead of repeating the same operation unchanged.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text describing the revised approach and how it differs from the failed attempt."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure that motivates the revision."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failed or partially failed operation.",
      "The reasoning identifies the element of the failed attempt that must change, for example environment-variable scope, execution identity, or command options.",
      "The reasoning states an alternative that incorporates that change and is intended to avoid the failure."
    ],
    "exclusion_conditions": [
      "The reasoning announces a plain retry of the same operation without modification.",
      "The reasoning only expresses confusion or disappointment about the failure.",
      "The revised step does not address the element that caused the failure."
    ]
  },
  {
    "name": "CONFIRMS_EXPECTED_OUTCOME_WITH_PROBE",
    "definition": "The reasoning states an expected observable outcome, a subsequent targeted action elicits that outcome from the running system, and the resulting observation reports a result that resolves whether the expectation is satisfied.",
    "parameters": [
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the expected observable outcome or acceptance criterion."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that performs the targeted check against the running system."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the result that is compared with the stated expectation."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a specific, observable expected outcome, such as a command returning particular content or a service accepting a request.",
      "The action is directed at eliciting exactly that outcome from the configured system.",
      "The observation reports a result whose content can be directly matched against the stated expectation."
    ],
    "exclusion_conditions": [
      "No expected outcome is stated before the check.",
      "The action is unrelated to the stated expectation.",
      "The observation reports output that cannot be interpreted relative to the expectation."
    ]
  },
  {
    "name": "TESTS_UNTESTED_PATH",
    "definition": "The reasoning identifies a specific execution path or condition that earlier verification did not cover, and the action deliberately exercises that uncovered path to check how the system handles it.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text naming the uncovered path or condition and why it needs coverage."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The action that deliberately exercises that previously uncovered path."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a concrete path or condition distinct from the cases already verified, such as updating an existing branch rather than creating it.",
      "The reasoning explains why that path could behave differently from the verified case.",
      "The action deliberately triggers that path."
    ],
    "exclusion_conditions": [
      "The action repeats a case already verified without a new distinguishing condition.",
      "The reasoning performs a routine step with no identified coverage gap.",
      "No specific uncovered path is articulated."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion about the state of the system or about a cause, supported by identifiable content of the observation rather than by assumption or repetition.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text stating the conclusion supported by the observation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the supporting content."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, such as a repository being empty or services being bound to all interfaces.",
      "Specific content of the observation, for example header length, empty reference listing, or socket states, supports the stated conclusion.",
      "The support link between the observation content and the conclusion is identifiable."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the observation without drawing a conclusion.",
      "The conclusion is asserted without any supporting content in the observation.",
      "The observation is used only as an operational input to a following action."
    ]
  },
  {
    "name": "ENUMERATES_REQUIRED_END_STATE",
    "definition": "The reasoning enumerates the conditions the environment must satisfy at handoff, decomposing the deliverable's final state into individually checkable invariants.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text listing the conditions the final environment must satisfy."
      }
    ],
    "assertion_conditions": [
      "The reasoning lists multiple distinct conditions the final environment must satisfy, such as services running, repository empty, keys removed, and host entries present.",
      "The listed conditions are phrased as checkable properties of the delivered state rather than as actions to perform."
    ],
    "exclusion_conditions": [
      "The reasoning describes steps to execute without stating resulting state conditions.",
      "The reasoning states only a single observation about current state with no enumeration of required end-state properties."
    ]
  },
  {
    "name": "IMPLEMENTS_GUARDED_RECOVERY",
    "definition": "The reasoning identifies that a required capability must survive interruption or restart, and the action creates a repeatable, non-failing mechanism that restores that capability only when it is absent, with the observation confirming the mechanism was created.",
    "parameters": [
      {
        "name": "resilience_reasoning",
        "type": "reasoning",
        "description": "The agent text identifying the need for the required capability to be restored after restart or interruption."
      },
      {
        "name": "creation_action",
        "type": "action",
        "description": "The action creating the guarded recovery mechanism."
      },
      {
        "name": "creation_result",
        "type": "observation",
        "description": "The observation confirming that the mechanism was written and made usable."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the mechanism as a safety net ensuring a required service stays available rather than as a one-time start.",
      "The created mechanism includes a presence check so it does not duplicate or restart an already-running capability.",
      "The created mechanism is specified to be silent and to succeed unconditionally so it cannot break the invoking session.",
      "The observation reports successful creation of the mechanism."
    ],
    "exclusion_conditions": [
      "The mechanism unconditionally starts the capability regardless of whether it is already running.",
      "The mechanism can fail or emit output that affects the caller.",
      "The intent is a one-time service start with no resilience or restart rationale."
    ]
  }
]

